package com.delivery.platform.payments.api;import com.delivery.platform.common.PageResponse;import com.delivery.platform.identity.security.IdentityPrincipal;import com.delivery.platform.payments.application.PaymentService;import com.delivery.platform.payments.application.PaymentService.*;import com.delivery.platform.payments.domain.PaymentTypes.Method;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api/v1") public class PaymentController{private final PaymentService service;public PaymentController(PaymentService service){this.service=service;}public record CreatePaymentRequest(@NotNull Method paymentMethod,@Size(max=160)String providerReference){}public record RefundPaymentRequest(@NotNull@Positive BigDecimal amount,@NotBlank@Size(max=500)String reason){}
 @PostMapping("/orders/{orderId}/payments")@PreAuthorize("hasAuthority('PAYMENT_CREATE')")Payment create(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID orderId,@RequestHeader("Idempotency-Key")String key,@Valid@RequestBody CreatePaymentRequest q){return service.create(p,orderId,q.paymentMethod(),q.providerReference(),key);}@GetMapping("/orders/{orderId}/payments")@PreAuthorize("hasAuthority('PAYMENT_VIEW')")List<Payment> order(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID orderId){return service.byOrder(p,orderId);}@GetMapping("/payments")@PreAuthorize("hasAuthority('PAYMENT_VIEW')")PageResponse<Payment> list(@AuthenticationPrincipal IdentityPrincipal p,@RequestParam(required=false)String status,@RequestParam(required=false)String method,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(p,status,method,page,size);}@GetMapping("/payments/{id}")@PreAuthorize("hasAuthority('PAYMENT_VIEW')")Payment one(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return service.one(p,id);}@PostMapping("/payments/{id}/confirm")@PreAuthorize("hasAuthority('PAYMENT_ADMIN')")Payment confirm(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return service.confirm(p,id);}@PostMapping("/payments/{id}/cancel")@PreAuthorize("hasAuthority('PAYMENT_ADMIN')")Payment cancel(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return service.cancel(p,id);}@PostMapping("/payments/{id}/refund")@PreAuthorize("hasAuthority('PAYMENT_REFUND')")Payment refund(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id,@RequestHeader("Idempotency-Key")String key,@Valid@RequestBody RefundPaymentRequest q){return service.refund(p,id,q.amount(),q.reason(),key);}@GetMapping("/payments/{id}/transactions")@PreAuthorize("hasAuthority('PAYMENT_VIEW')")List<Transaction> tx(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return service.transactions(p,id);}}
